<template>
  <div class="app-container">
    <el-alert v-if="resource==='assets'" title="先创建行业知识空间，再把资料归入对应行业；只有已归类资料会参与该行业的本体分析。资料可上传或粘贴，之后可单独点击“整理 Wiki”。" type="info" :closable="false" class="notice" />
    <el-alert v-if="resource==='datasources'" title="密码单独加密保存；扫描时可指定表名和样例条数，样例仅发送到已配置的模型 API。" type="info" :closable="false" class="notice" />
    <el-alert v-if="resource==='analyses'" title="每个分析任务必须绑定一个行业知识空间；系统只读取该空间内的 Wiki 资产，不会混用其他行业资料。数据库结构仍从所选数据源独立扫描。" type="info" :closable="false" class="notice" />
    <el-alert v-if="resource==='proposals'" title="待审核草案由拥有“草案审核”权限的本体工程师处理，系统会记录审核人、时间和意见。审核通过后才可导入；逻辑和动作仍需在本体平台测试。" type="info" :closable="false" class="notice" />
    <el-form v-show="showSearch" :inline="true" :model="query" size="small">
      <el-form-item><el-input v-model="query.keyword" placeholder="名称 / 描述 / 类型" clearable @keyup.enter.native="search" /></el-form-item>
      <el-form-item><el-button type="primary" icon="el-icon-search" @click="search">搜索</el-button><el-button @click="reset">重置</el-button></el-form-item>
    </el-form>
    <el-row class="mb8"><el-button v-hasPermi="[perm + ':add']" type="primary" plain icon="el-icon-plus" size="mini" @click="edit()">新增{{ title }}</el-button><el-tag v-if="resource==='assets' && query.spaceId" size="small" closable @close="clearSpaceFilter">行业筛选：{{ spaceName(query.spaceId) }}</el-tag><el-tag v-if="resource==='proposals' && query.taskId" size="small" closable @close="clearTaskFilter">来源任务：{{ proposalTaskName || ('任务 #' + query.taskId) }}</el-tag><el-radio-group v-if="resource==='assets'" v-model="assetView" size="mini" class="asset-view-switch"><el-radio-button label="list">资产列表</el-radio-button><el-radio-button label="graph">关联图</el-radio-button></el-radio-group><right-toolbar :showSearch.sync="showSearch" @queryTable="load" /></el-row>
    <div v-if="resource==='assets' && assetView==='graph'" v-loading="assetGraphLoading" class="asset-graph-panel"><div class="asset-graph-note">连线表示来源资料已整理为 Wiki 页面；点击节点可查看资产内容。</div><div v-if="assetGraph.nodes && assetGraph.nodes.length" ref="assetGraphChart" class="asset-relation-graph"/><el-empty v-else :image-size="64" description="当前没有可展示的 Wiki 资产" /></div>
    <el-table v-if="resource!=='assets' || assetView==='list'" v-loading="loading" :data="rows" border>
      <el-table-column v-for="col in columns" :key="col.key" :prop="col.key" :label="col.key==='source_id' ? '数据源' : (col.key==='wiki_space_id' ? '行业知识空间' : (col.key==='review_by' ? '审核记录' : col.label))" min-width="130" show-overflow-tooltip><template slot-scope="s"><el-tag v-if="resource==='analyses' && col.key==='status'" size="mini" :type="analysisStatusType(s.row.status)">{{ analysisStatusText(s.row.status) }}</el-tag><el-tag v-else-if="resource==='proposals' && col.key==='status'" size="mini" :type="proposalStatusType(s.row.status)">{{ proposalStatusText(s.row.status) }}</el-tag><el-tag v-else-if="col.key==='status'" size="mini" :type="resourceStatusType(s.row.status)">{{ resourceStatusText(s.row.status) }}</el-tag><span v-else-if="resource==='proposals' && col.key==='proposal_type'">{{ proposalTypeText(s.row.proposal_type) }}</span><span v-else-if="resource==='proposals' && col.key==='review_by'">{{ s.row.review_by ? s.row.review_by + ' · ' + (s.row.review_time || '') + ' · ' + (s.row.review_comment || '无意见') : '尚未审核' }}</span><span v-else-if="resource==='assets' && col.key==='asset_type'">{{ assetTypeText(s.row.asset_type) }}</span><span v-else-if="resource==='datasources' && col.key==='db_type'">{{ datasourceTypeText(s.row.db_type) }}</span><span v-else>{{ col.key==='source_id' ? sourceName(s.row.source_id) : ((col.key==='space_id' || col.key==='wiki_space_id') ? spaceName(s.row[col.key]) : s.row[col.key]) }}</span></template></el-table-column>
      <el-table-column label="操作" width="740" fixed="right"><template slot-scope="s"><el-button v-if="resource==='spaces'" v-hasPermi="['ontology:assets:list']" type="text" @click="openSpaceAssets(s.row)">查看资料</el-button><el-button v-if="resource==='spaces'" v-hasPermi="['ontology:dashboard:list']" type="text" @click="openScopedChat('SPACE',s.row.space_id)">行业问答</el-button><el-button v-if="resource==='assets'" v-hasPermi="[perm + ':query']" type="text" @click="viewAsset(s.row)">查看</el-button><el-button v-if="resource==='assets'" v-hasPermi="['ontology:dashboard:list']" type="text" @click="openScopedChat('ASSET',s.row.asset_id)">基于此资料问答</el-button><el-button v-if="resource==='assets' && s.row.asset_type!=='WIKI_PAGE' && s.row.asset_type!=='URL'" v-hasPermi="[perm + ':edit']" type="text" @click="ingest(s.row)">整理 Wiki</el-button><el-button v-if="resource==='datasources'" v-hasPermi="[perm + ':query']" type="text" @click="testSavedConnection(s.row)">测试连接</el-button><el-button v-if="resource==='datasources'" v-hasPermi="[perm + ':edit']" type="text" @click="credential(s.row)">设置密码</el-button><el-button v-if="resource==='datasources'" v-hasPermi="[perm + ':query']" type="text" @click="scan(s.row)">扫描</el-button><el-button v-if="resource==='analyses'" v-hasPermi="['ontology:dashboard:list']" type="text" @click="openScopedChat('ANALYSIS',s.row.task_id)">任务问答</el-button><el-button v-if="resource==='analyses'" v-hasPermi="[perm + ':edit']" type="text" :disabled="s.row.status==='RUNNING'" @click="analyze(s.row)">{{ s.row.status==='RUNNING' ? '分析中…' : (s.row.status==='DONE' ? '重新分析并生成版本' : '执行分析') }}</el-button><el-button v-if="resource==='analyses' && s.row.status==='DONE'" v-hasPermi="['ontology:proposals:list']" type="text" @click="openTaskProposal(s.row)">配置草案</el-button><el-button v-if="resource==='proposals'" v-hasPermi="[perm + ':query']" type="text" @click="viewProposal(s.row)">查看</el-button><el-button v-if="resource==='proposals'" v-hasPermi="[perm + ':edit']" type="text" @click="sandboxTestProposalRow(s.row)">沙箱测试</el-button><el-button v-if="resource==='proposals' && s.row.status==='DRAFT'" v-hasPermi="['ontology:proposals:review']" type="text" @click="reviewProposalRow(s.row,'APPROVED')">审核通过</el-button><el-button v-if="resource==='proposals' && s.row.status==='DRAFT'" v-hasPermi="['ontology:proposals:review']" type="text" @click="reviewProposalRow(s.row,'REJECTED')">驳回</el-button><el-button v-if="resource==='proposals'" v-hasPermi="[perm + ':query']" type="text" @click="downloadProposal(s.row,'rdf')">导出 RDF/OWL</el-button><el-button v-if="resource==='proposals'" v-hasPermi="[perm + ':query']" type="text" @click="downloadProposal(s.row,'project')">导出工程</el-button><el-button v-if="resource==='proposals' && s.row.status==='APPROVED'" v-hasPermi="[perm + ':edit']" type="text" @click="importProposalRow(s.row)">导入本体平台</el-button><el-button v-hasPermi="[perm + ':edit']" type="text" @click="edit(s.row)">{{ resource==='proposals' ? '高级编辑' : '编辑' }}</el-button><el-button v-hasPermi="[perm + ':remove']" type="text" @click="remove(s.row)">删除</el-button></template></el-table-column>
    </el-table>
    <pagination v-show="total>0 && (resource!=='assets' || assetView==='list')" :total="total" :page.sync="query.pageNum" :limit.sync="query.pageSize" @pagination="load" />
    <el-dialog v-if="resource==='assets'" :title="form.id ? '编辑资料' : '新增资料'" :visible.sync="open" width="720px" append-to-body>
      <el-form ref="assetForm" :model="form" label-width="92px">
        <el-form-item label="资料名称" required><el-input v-model="form.asset_name" placeholder="例如：订单业务说明、客户管理制度" /></el-form-item>
        <el-form-item label="输入方式"><el-radio-group v-model="assetInputMode"><el-radio-button label="text">粘贴文本</el-radio-button><el-radio-button label="file">上传文件</el-radio-button></el-radio-group></el-form-item>
        <el-form-item v-if="assetInputMode==='file'" label="资料文件"><input ref="assetFile" type="file" accept=".txt,.md,.csv,.json,.yaml,.yml,.sql,.xml,.log" style="display:none" @change="readAssetFile"><el-button icon="el-icon-upload2" @click="$refs.assetFile.click()">选择文本文件</el-button><span v-if="assetFileName" class="asset-file-name">{{ assetFileName }}</span><div class="form-tip">支持 TXT、Markdown、CSV、JSON、YAML、SQL、XML 等文本文件，单个文件不超过 5MB</div></el-form-item>
        <el-form-item label="资料内容" required><el-input v-model="form.content" type="textarea" :rows="12" placeholder="粘贴业务制度、字段说明、流程文档、问答案例等内容" /></el-form-item>
        <el-form-item label="备注"><el-input v-model="form.description" placeholder="可选，用于说明资料来源或适用范围" /></el-form-item>
      </el-form>
      <span slot="footer"><el-button type="primary" @click="saveAsset">保存资料</el-button><el-button @click="open=false">取消</el-button></span>
    </el-dialog>
    <el-dialog title="Wiki 整理结果" :visible.sync="wikiResultOpen" width="900px" append-to-body>
      <el-alert :title="'已' + (wikiResult.updated ? '更新' : '生成') + '并保存 Wiki 页面。请检查模型整理的事实和规则，再用于本体分析。'" type="success" :closable="false" />
      <h3 class="wiki-result-title">{{ wikiResult.title }}</h3>
      <p v-if="wikiResult.summary" class="wiki-result-summary">{{ wikiResult.summary }}</p>
      <pre class="wiki-result-content">{{ wikiResult.content }}</pre>
      <span slot="footer"><el-button type="primary" @click="wikiResultOpen=false">知道了</el-button></span>
    </el-dialog>
    <el-dialog :title="assetPreview.asset_type==='WIKI_PAGE' ? 'Wiki 页面' : '资料详情'" :visible.sync="assetPreviewOpen" width="900px" append-to-body>
      <div class="asset-preview-meta"><strong>{{ assetPreview.asset_name }}</strong><el-tag size="mini">{{ assetTypeText(assetPreview.asset_type) }}</el-tag></div>
      <p v-if="assetPreview.description" class="wiki-result-summary">{{ assetPreview.description }}</p>
      <pre class="wiki-result-content">{{ assetPreview.content || '暂无内容' }}</pre>
      <span slot="footer"><el-button @click="assetPreviewOpen=false">关闭</el-button></span>
    </el-dialog>
    <el-dialog title="分析进度" :visible.sync="analysisProgress.visible" width="680px" append-to-body :close-on-click-modal="false" :show-close="analysisProgress.status!=='RUNNING' && !!analysisResult.proposalConfig">
      <div class="analysis-progress-current"><i v-if="analysisProgress.status==='RUNNING'" class="el-icon-loading"/><i v-else-if="analysisProgress.status==='DONE'" class="el-icon-circle-check"/><i v-else class="el-icon-circle-close"/><span>{{ analysisProgress.message }}</span><small>已用时 {{ analysisProgress.elapsedSeconds }} 秒</small></div>
      <el-steps :active="Math.max((analysisProgress.step || 1)-1, 0)" finish-status="success" simple class="analysis-progress-steps">
        <el-step title="读取数据库"/><el-step title="生成候选"/><el-step title="模型分析"/><el-step title="保存草案"/>
      </el-steps>
      <div class="analysis-progress-log"><div v-for="(item,index) in analysisProgress.logs" :key="index"><time>{{ item.time }}</time><span>{{ item.message }}</span></div></div>
      <el-alert v-if="analysisProgress.status==='FAILED'" :title="analysisProgress.error || '分析失败，请检查数据源和模型服务状态。'" type="error" :closable="false" />
      <span slot="footer"><el-button v-if="analysisProgress.status==='DONE'" type="primary" :disabled="!analysisResult.proposalConfig" @click="openAnalysisResult">查看分析结果</el-button><el-button v-if="analysisProgress.status!=='RUNNING'" @click="analysisProgress.visible=false">关闭</el-button></span>
    </el-dialog>
    <el-dialog v-if="resource!=='assets'" :title="form.id ? '编辑' + title : '新增' + title" :visible.sync="open" width="720px" append-to-body>
      <el-alert v-if="resource==='analyses' && !datasourceOptions.length" title="请先在数据源管理中配置并测试数据源，再创建分析任务。" type="warning" :closable="false" style="margin-bottom:16px" />
      <el-form ref="form" :model="form" :rules="rules" label-width="110px">
        <template v-if="resource==='datasources'">
          <el-form-item label="数据源名称" prop="name" required><el-input v-model="form.name" maxlength="100" placeholder="例如：生产 PostgreSQL" /></el-form-item>
          <el-form-item label="连接方式" required><el-radio-group v-model="connectionMode"><el-radio-button label="host">主机配置</el-radio-button><el-radio-button label="jdbc">JDBC URL</el-radio-button></el-radio-group></el-form-item>
          <el-form-item label="数据库类型" prop="db_type" required><el-select v-model="form.db_type" :disabled="connectionMode==='jdbc' && !jdbcUrlError && !!form.jdbc_url" style="width:100%" @change="databaseTypeChanged"><el-option label="MySQL" value="mysql"/><el-option label="PostgreSQL" value="postgresql"/><el-option label="Hive" value="hive"/></el-select><div v-if="connectionMode==='jdbc'" class="form-tip">JDBC 地址有效时自动识别数据库类型</div></el-form-item>
          <template v-if="connectionMode==='jdbc'">
            <el-form-item label="JDBC URL" prop="jdbc_url" required><el-input v-model="form.jdbc_url" placeholder="jdbc:postgresql://db.example.com:5432/app?currentSchema=public" @input="parseDatasourceJdbcUrl"/><div v-if="jdbcUrlError" class="form-error">{{ jdbcUrlError }}</div><div v-else class="form-tip">支持 MySQL、PostgreSQL、Hive；账号密码请填写在下方，不要写入 URL。</div></el-form-item>
            <el-form-item label="识别结果"><el-input :value="[form.host, form.port, form.database_name].filter(Boolean).join(' / ') || '输入 JDBC URL 后自动识别'" disabled/></el-form-item>
          </template>
          <template v-else>
            <el-form-item label="主机地址" prop="host" required><el-input v-model="form.host" placeholder="数据库 IP 或域名"/></el-form-item>
            <el-form-item label="端口" prop="port" required><el-input v-model="form.port" placeholder="按数据库类型自动填入默认端口"/></el-form-item>
            <el-form-item label="数据库名" prop="database_name" required><el-input v-model="form.database_name" placeholder="要连接的数据库"/></el-form-item>
          </template>
          <el-form-item v-if="String(form.db_type).toLowerCase()==='postgresql' || String(form.db_type).toLowerCase()==='postgres'" label="Schema"><el-input v-model="form.schema_name" placeholder="可留空，扫描驱动可见的全部 Schema"/><div class="form-tip">仅 PostgreSQL 需要；其他数据库不显示此项。</div></el-form-item>
          <el-form-item label="用户名" prop="username" required><el-input v-model="form.username" placeholder="数据库账号"/></el-form-item>
          <el-form-item label="数据库密码" prop="password" :required="!form.id"><el-input v-model="form.password" type="password" show-password :placeholder="form.id ? '留空则继续使用已保存密码' : '请输入数据库密码'"/><div v-if="form.id" class="form-tip">密码单独加密保存；留空不会覆盖已保存密码。</div></el-form-item>
          <el-form-item label="默认样例条数"><el-input-number v-model="form.sample_limit" :min="0" :max="20"/></el-form-item>
          <el-form-item label="说明"><el-input v-model="form.description" type="textarea" :rows="3" maxlength="500" show-word-limit/></el-form-item>
        </template>
        <el-form-item v-for="field in fields" v-if="resource!=='datasources' && !field.formHidden" :key="field.key" :label="field.label" :prop="field.key">
          <el-select v-if="resource==='analyses' && field.key==='source_id'" v-model="form[field.key]" filterable clearable placeholder="请选择已配置的数据源" style="width:100%"><el-option v-for="item in datasourceOptions" :key="item.datasource_id" :label="datasourceLabel(item)" :value="item.datasource_id" /></el-select>
          <el-select v-else-if="resource==='analyses' && field.key==='wiki_space_id'" v-model="form.wiki_space_id" filterable placeholder="请选择行业知识空间" style="width:100%"><el-option v-for="item in spaceOptions" :key="item.space_id" :label="item.space_name" :value="item.space_id" /></el-select>
          <el-select v-else-if="resource==='assets' && field.key==='space_id'" v-model="form.space_id" filterable placeholder="请选择所属行业知识空间" style="width:100%"><el-option v-for="item in spaceOptions" :key="item.space_id" :label="item.space_name" :value="item.space_id" /></el-select>
          <el-select v-else-if="field.options" v-model="form[field.key]" style="width:100%"><el-option v-for="o in field.options" :key="o.value" :label="o.label" :value="o.value" /></el-select>
          <el-input v-else-if="field.long" v-model="form[field.key]" type="textarea" :rows="field.json ? 12 : 4" :placeholder="field.json ? '填写本体配置 JSON' : ''" />
          <el-input v-else-if="field.secret" v-model="form[field.key]" type="password" show-password :placeholder="field.placeholder || ''" />
          <el-input v-else v-model="form[field.key]" :placeholder="field.placeholder || ''" />
          <div v-if="resource==='analyses' && field.key==='scope'" class="form-tip">描述业务关注点即可；如需动作和权限候选，可补充 SQL 样例（每行一条 SELECT / INSERT / UPDATE / DELETE）。样例仅在本地识别操作与表，不会执行或发送给模型，请勿包含真实数据。</div>
          <div v-if="resource==='analyses' && field.key==='wiki_space_id'" class="form-tip">一个行业知识空间对应一类业务；分析只使用该空间绑定的 Wiki 资产，不会读取其他行业资料。</div>
        </el-form-item>
      </el-form>
      <span slot="footer"><el-button v-if="resource==='datasources'" :loading="testing" @click="testFormConnection">测试连接</el-button><el-button type="primary" @click="save">保存</el-button><el-button @click="open=false">取消</el-button></span>
    </el-dialog>
    <el-dialog custom-class="proposal-detail-dialog" :title="analysisResult.isSavedProposal ? '配置草案详情' : '本体生成草案'" :visible.sync="analysisOpen" width="1120px" append-to-body>
      <el-alert :title="'草案 #' + (analysisResult.proposalId || '未保存') + ' · ' + proposalStatusText(analysisResult.status || 'DRAFT') + ' · 生成内容均为候选，请审核并在本体平台沙箱验证。'" type="warning" :closable="false" />
      <div class="proposal-detail-head"><div><p v-if="analysisResult.proposalName" class="proposal-view-name">{{ analysisResult.proposalName }}</p><span class="proposal-detail-meta">分析任务：{{ analysisResult.taskName || ('任务 #' + (analysisResult.taskId || '—')) }}</span></div><div class="proposal-head-actions"><el-button size="small" icon="el-icon-chat-dot-round" @click="openAnswerChat">进入知识问答优化</el-button><el-button v-if="analysisResult.isSavedProposal" size="small" type="primary" @click="downloadCurrentProposal('rdf')">导出 OWL</el-button></div></div>
      <div v-if="resource==='proposals' && analysisResult.taskId" class="proposal-versions"><div class="proposal-section-title"><strong>版本列表</strong><span>按生成时间倒序，选择版本查看对应候选与审核状态</span></div><div class="proposal-version-list"><button v-for="version in proposalVersions" :key="version.proposal_id" type="button" :class="['proposal-version', { active: String(version.proposal_id)===String(analysisResult.proposalId) }]" @click="selectProposalVersion(version)"><span class="version-number">第{{ versionNumber(version) }}版</span><span class="version-name">{{ version.proposal_name }}</span><span class="version-tags"><el-tag v-if="String(version.proposal_id)===String(analysisResult.proposalId)" size="mini" type="primary">当前查看</el-tag><el-tag size="mini" :type="proposalStatusType(version.status)">{{ proposalStatusText(version.status) }}</el-tag></span><small>{{ version.update_time || version.create_time || '' }}</small></button></div></div>
      <el-row :gutter="12" class="analysis-counts">
        <el-col :span="6"><div class="count-card"><strong>{{ countOf(analysisConfig.objects) }}</strong><span>对象</span></div></el-col>
        <el-col :span="6"><div class="count-card"><strong>{{ countOf(analysisConfig.properties) }}</strong><span>属性</span></div></el-col>
        <el-col :span="6"><div class="count-card"><strong>{{ countOf(analysisConfig.relations) }}</strong><span>关系</span></div></el-col>
        <el-col :span="6"><div class="count-card"><strong>{{ countOf(analysisConfig.logics) + countOf(analysisConfig.actions) }}</strong><span>逻辑 / 动作</span></div></el-col>
      </el-row>
      <el-tabs v-model="analysisTab">
        <el-tab-pane label="对象与属性" name="objects">
          <el-table :data="analysisConfig.objects || []" max-height="340" border>
            <el-table-column label="候选对象" min-width="180"><template slot-scope="s">{{ objectLabel(s.row) }}</template></el-table-column>
            <el-table-column prop="table" label="物理表" min-width="180"/>
            <el-table-column label="置信度" width="100"><template slot-scope="s">{{ formatConfidence(s.row.confidence) }}</template></el-table-column>
            <el-table-column label="状态" width="120"><template slot-scope="s"><el-tag size="mini" type="warning">{{ candidateStatusText(s.row.status) }}</el-tag></template></el-table-column>
          </el-table>
          <el-table :data="analysisConfig.properties || []" max-height="280" border class="sub-table">
            <el-table-column label="候选属性" min-width="180"><template slot-scope="s">{{ propertyLabel(s.row) }}</template></el-table-column>
            <el-table-column label="所属对象" min-width="220"><template slot-scope="s">{{ objectName(s.row.objectId) }}</template></el-table-column>
            <el-table-column prop="column" label="物理字段" min-width="160"/>
