<script>
import { listResource, getResource, getAssetGraph, addResource, updateResource, deleteResource, setDatasourceCredential, testDatasource, scanDatasource, analyzeTask, importProposal, reviewProposal, exportProposal, proposalDiff, sandboxTestProposal, ingestWikiAsset } from '@/api/ontology'
import * as echarts from 'echarts'
const configs = {
  spaces: { title: '行业知识空间', fields: [{ key: 'space_name', label: '行业 / 业务域名称', required: true }, { key: 'description', label: '说明', long: true }, { key: 'status', label: '状态', options: [{label:'正常',value:'0'},{label:'停用',value:'1'}] }] },
  assets: { title: 'Wiki资产', fields: [{ key: 'asset_name', label: '资料名称', required: true }, { key: 'space_id', label: '所属行业知识空间', required: true }, { key: 'asset_type', label: '资料类型', options: [{label:'文本',value:'TEXT'},{label:'文件',value:'FILE'}] }, { key: 'description', label: '备注' }] },
  datasources: { title: '数据源', fields: [{ key: 'name', label: '名称', required: true }, { key: 'db_type', label: '数据库类型', required: true }, { key: 'host', label: '主机地址' }, { key: 'port', label: '端口' }, { key: 'database_name', label: '数据库名' }, { key: 'schema_name', label: 'Schema' }, { key: 'jdbc_url', label: 'JDBC URL' }, { key: 'username', label: '用户名' }, { key: 'password', label: '数据库密码', secret: true, hidden: true, placeholder: '编辑已有数据源可留空，使用已保存密码' }, { key: 'sample_limit', label: '默认样例条数' }, { key: 'description', label: '说明', long: true }] },
  analyses: { title: '分析任务', fields: [{ key: 'task_name', label: '任务名称', required: true }, { key: 'source_id', label: '关联数据源', required: true }, { key: 'wiki_space_id', label: '分析行业', required: true }, { key: 'scope', label: '分析范围', long: true }, { key: 'status', label: '状态', formHidden: true, options: ['DRAFT','READY','RUNNING','DONE','FAILED'].map(x => ({ label:x, value:x })) }, { key: 'summary', label: '分析结论', formHidden: true, long: true }] },
  proposals: { title: '配置草案', fields: [{ key: 'proposal_name', label: '草案名称', required: true }, { key: 'proposal_type', label: '配置类型', required: true, options: [{label:'本体配置包',value:'ONTOLOGY_BUNDLE'},{label:'对象',value:'对象'},{label:'逻辑',value:'逻辑'},{label:'动作',value:'动作'},{label:'关系',value:'关系'}] }, { key: 'task_name', label: '来源分析任务', formHidden: true }, { key: 'task_id', label: '来源任务编号', formHidden: true, hidden: true }, { key: 'config_json', label: '配置JSON', long: true, json: true, hidden: true }, { key: 'status', label: '状态', formHidden: true }, { key: 'review_by', label: '审核人', formHidden: true }, { key: 'review_time', label: '审核时间', formHidden: true, hidden: true }, { key: 'review_comment', label: '审核意见', formHidden: true, hidden: true }] },
  imports: { title: '导入记录', fields: [{ key: 'proposal_id', label: '草案ID' }, { key: 'target_system', label: '目标本体平台' }, { key: 'status', label: '状态', options: ['PENDING','SUCCESS','FAILED'].map(x => ({ label:x, value:x })) }, { key: 'detail', label: '导入详情', long: true }] }
}
export default {
  name: 'OntologyResource',
  data() { const raw = this.$route.path.split('/').filter(Boolean).pop(); const aliases={datasource:'datasources',analysis:'analyses',proposal:'proposals',import:'imports',space:'spaces',asset:'assets'}; const key = aliases[raw] || raw; const c = configs[key] || configs.assets; const ids={spaces:'space_id',assets:'asset_id',datasources:'datasource_id',analyses:'task_id',proposals:'proposal_id',imports:'import_id'}; const idLabels={spaces:'空间编号',assets:'资料编号',datasources:'数据源编号',analyses:'任务编号',proposals:'草案编号',imports:'导入编号'}; return { resource: key, title: c.title, fields: c.fields, columns: [{key:ids[key],label:idLabels[key]}, ...c.fields.filter(f => !f.hidden)], rows:[], total:0, loading:false, testing:false, showSearch:true, open:false, assetView:'list', assetGraphLoading:false, assetGraph:{nodes:[],edges:[]}, assetGraphChart:null, connectionMode:'host', jdbcUrlError:'', assetPreviewOpen:false, assetPreview:{}, wikiResultOpen:false, wikiResult:{}, analysisProgress:{ visible:false, status:'', step:1, message:'', elapsedSeconds:0, error:'', logs:[] }, analysisProgressTimer:null, analysisStartedAt:0, analysisOpen:false, analysisTab:'objects', analysisResult:{}, analysisConfig:{}, proposalVersions:[], graphChart:null, proposalTaskName:'', diffOpen:false, diffLoading:false, diffInfo:{}, datasourceOptions:[], spaceOptions:[], assetInputMode:'text', assetFileName:'', query:{ pageNum:1,pageSize:20,keyword:'',spaceId:undefined,taskId:undefined }, form:{}, rules:Object.fromEntries(c.fields.filter(f => f.required).map(f => [f.key,[{required:true,message:f.label+'不能为空',trigger:'blur'}]])) } },
  filters: { shortText(value) { const text=String(value || ''); return text.length>100 ? text.slice(0,100)+'…' : text } },
  computed: { perm() { return 'ontology:' + this.resource } },
  watch: { analysisTab(value) { if (value === 'graph') this.$nextTick(this.renderGraph) }, assetView(value) { if (value === 'graph') this.loadAssetGraph() } },
  created() { this.query.spaceId=this.resource==='assets' && this.$route.query.spaceId ? Number(this.$route.query.spaceId) : undefined; const taskId=Number(this.$route.query.taskId); this.query.taskId=this.resource==='proposals' && Number.isFinite(taskId) && taskId>0 ? taskId : undefined; this.proposalTaskName=this.resource==='proposals' ? String(this.$route.query.taskName || '') : ''; const proposalId=this.resource==='proposals' ? String(this.$route.query.proposalId || '') : ''; this.load().then(() => { if (!proposalId) return; const row=this.rows.find(item => String(item.proposal_id)===proposalId); if (row) this.viewProposal(row); else getResource('proposals', proposalId).then(({ data }) => data && this.viewProposal(data)).catch(() => {}) }); if (this.resource==='analyses') { this.loadDatasources(); this.loadSpaces(); if (this.$route.query.new==='1') { this.form={ task_name:'问答转本体分析', wiki_space_id:this.$route.query.wiki_space_id ? Number(this.$route.query.wiki_space_id) : null, scope:this.$route.query.scope || '' }; this.open=true; this.$nextTick(() => this.$router.replace({ path:this.$route.path, query:{} }).catch(() => {})) } } if (this.resource==='assets') this.loadSpaces() },
  beforeDestroy() { this.stopAnalysisProgress(); if (this.graphChart) this.graphChart.dispose(); if (this.assetGraphChart) this.assetGraphChart.dispose() },
  methods: {
    load() { this.loading=true; return listResource(this.resource,this.query).then(r => { this.rows=r.rows || []; this.total=r.total || 0 }).finally(() => { this.loading=false }) },
    loadAssetGraph() { if (this.resource!=='assets' || this.assetGraphLoading) return; this.assetGraphLoading=true; getAssetGraph(this.query.spaceId ? { spaceId:this.query.spaceId } : undefined).then(({data}) => { this.assetGraph=data || {nodes:[],edges:[]}; this.$nextTick(this.renderAssetGraph) }).catch(() => { this.assetGraph={nodes:[],edges:[]}; this.$modal.msgError('资产关联图加载失败') }).finally(() => { this.assetGraphLoading=false }) },
    renderAssetGraph() { const box=this.$refs.assetGraphChart; if (!box || !this.assetGraph.nodes.length) return; if (this.assetGraphChart) this.assetGraphChart.dispose(); this.assetGraphChart=echarts.init(box); this.assetGraphChart.setOption({ animationDuration:350, tooltip:{ formatter:params => params.dataType==='edge' ? (params.data.name || '关联资产') : `${params.data.name}<br/>${this.assetTypeText(params.data.assetType)}` }, series:[{ type:'graph', layout:'force', roam:true, draggable:true, data:this.assetGraph.nodes.map(item => ({ id:String(item.id), assetId:item.assetId, name:item.name, assetType:item.assetType, symbolSize:item.assetType==='WIKI_PAGE'?54:44, itemStyle:{ color:item.assetType==='WIKI_PAGE'?'#0075de':'#c28b55' } })), links:this.assetGraph.edges, force:{ repulsion:240, edgeLength:150 }, label:{ show:true, color:'#31302e', fontSize:12 }, lineStyle:{ color:'#a39e98', opacity:.75, width:1.5 }, edgeLabel:{ show:true, formatter:params => params.data.name || '', color:'#716b66', fontSize:10 } }] }); this.assetGraphChart.off('click'); this.assetGraphChart.on('click', params => { if (params.dataType==='node' && params.data.assetId) this.viewAsset({asset_id:params.data.assetId}) }) },
    clearSpaceFilter() { this.query.spaceId=undefined; const query=Object.assign({},this.$route.query); delete query.spaceId; this.$router.replace({query}).catch(() => {}); this.load() },
    clearTaskFilter() { this.query.taskId=undefined; this.proposalTaskName=''; this.query.pageNum=1; const query=Object.assign({},this.$route.query); delete query.taskId; delete query.taskName; this.$router.replace({ path:this.$route.path, query }).catch(() => {}); this.load() },
    openSpaceAssets(row) { this.$router.push({ path:'/ontology/assets', query:{ spaceId:row.space_id } }) },
    openScopedChat(type, id) { const query={ scopeType:type, scopeId:String(id) }; if (type==='SPACE') query.spaceId=String(id); this.$router.push({ path:'/ontology/chat', query }) },
    loadDatasources() { listResource('datasources', { pageNum:1, pageSize:100 }).then(r => { this.datasourceOptions=r.rows || [] }).catch(() => this.$modal.msgError('数据源列表加载失败，请刷新页面重试')) },
    loadSpaces() { listResource('spaces', { pageNum:1, pageSize:100 }).then(r => { this.spaceOptions=(r.rows || []).filter(item => String(item.status)!=='1') }).catch(() => this.$modal.msgError('行业知识空间加载失败，请刷新页面重试')) },
    spaceName(id) { const item=this.spaceOptions.find(x => String(x.space_id)===String(id)); return item ? item.space_name : (id ? `行业空间 ${id}` : '未关联行业') },
    datasourceLabel(item) { return `${item.name || '未命名数据源'}（${this.datasourceTypeText(item.db_type)} / ${item.database_name || '未填写库名'}）` },
    sourceName(id) { const item=this.datasourceOptions.find(x => String(x.datasource_id)===String(id)); return item ? this.datasourceLabel(item) : (id ? `数据源 #${id}` : '未配置') },
    analysisStatusText(status) { return ({DRAFT:'待执行',READY:'待执行',RUNNING:'分析中',DONE:'已完成',FAILED:'失败'})[status] || status || '未知' },
    analysisStatusType(status) { return ({DRAFT:'info',READY:'info',RUNNING:'warning',DONE:'success',FAILED:'danger'})[status] || 'info' },
    proposalStatusText(status) { return ({DRAFT:'待审核',REVIEWED:'待审核',APPROVED:'审核通过',REJECTED:'已驳回',IMPORTED:'已导入'})[status] || status || '未知状态' },
    proposalStatusType(status) { return ({DRAFT:'warning',REVIEWED:'info',APPROVED:'success',REJECTED:'danger',IMPORTED:'success'})[status] || 'info' },
    versionNumber(version) { const index=this.proposalVersions.findIndex(item => String(item.proposal_id)===String(version && version.proposal_id)); return version && version.version ? version.version : (index < 0 ? '—' : this.proposalVersions.length - index) },
    proposalTypeText(type) { return ({ONTOLOGY_BUNDLE:'本体配置包',对象:'对象',逻辑:'逻辑',动作:'动作',关系:'关系'})[type] || type || '未知类型' },
    assetTypeText(type) { return ({TEXT:'文本',FILE:'文件',WIKI_PAGE:'Wiki 页面',URL:'网页链接'})[type] || type || '未知类型' },
    datasourceTypeText(type) { return ({mysql:'MySQL',postgresql:'PostgreSQL',hive:'Hive'})[String(type || '').toLowerCase()] || type || '未知类型' },
    resourceStatusText(status) { return ({'0':'正常','1':'停用',PENDING:'待提交',SUCCESS:'导入成功',FAILED:'导入失败'})[status] || status || '未知状态' },
    resourceStatusType(status) { return ({'0':'success','1':'info',PENDING:'warning',SUCCESS:'success',FAILED:'danger'})[status] || 'info' },
