    analyze(row) { if (row.status!=='DONE') return this.runAnalysis(row,{}); this.$prompt('填写发生变化的表名（逗号分隔，包括新增或删除的表，最多20张）；留空则全量重扫。','生成新版本',{inputValue:'',inputPlaceholder:'例如 orders, order_item；留空=全量重扫'}).then(({value}) => { const names=Array.from(new Set(String(value || '').split(',').map(name => name.trim()).filter(Boolean))); if (names.length>20) return this.$modal.msgError('单次增量更新最多选择20张表'); this.runAnalysis(row,names.length?{mode:'INCREMENTAL',tables:names.join(',')}:{}); }).catch(() => {}) },
    runAnalysis(row, request) { const message=request.mode==='INCREMENTAL'?'系统将只重新读取所列变化表的结构，与上一个版本的其他表快照合并后重新生成候选，并保存一个新版本。是否继续？':'系统将全量扫描当前任务范围并保存一个新版本，完成后可比较与上一版本的差异。是否继续？'; this.$modal.confirm(message).then(() => { this.startAnalysisProgress(row.task_id); analyzeTask(row.task_id, request).then(result => { this.analysisResult=Object.assign({ isSavedProposal:true, taskId:row.task_id, taskName:row.task_name },result.data || {}); this.analysisConfig=this.analysisResult.proposalConfig || {}; this.analysisTab='objects'; this.analysisProgress.status='DONE'; this.analysisProgress.step=4; this.analysisProgress.message='分析完成，配置草案已保存；可进入知识问答修正分析结构'; this.analysisProgress.error=''; this.addAnalysisProgressLog('分析完成，配置草案 #' + (this.analysisResult.proposalId || '已保存')); this.stopAnalysisProgress(); this.load() }).catch(error => { this.analysisProgress.status='FAILED'; this.analysisProgress.message='分析失败'; this.analysisProgress.error=error && error.message ? error.message : '请检查数据源和模型服务状态'; this.addAnalysisProgressLog('分析失败：' + this.analysisProgress.error); this.stopAnalysisProgress(); this.load() }) }).catch(() => {}) },
