    viewProposal(row) { getResource('proposals',row.proposal_id).then(({data}) => { let config; try { config=typeof data.config_json==='string' ? JSON.parse(data.config_json) : data.config_json } catch (e) { this.$modal.msgError('草案配置无法解析，请联系管理员检查数据'); return } if (!config || typeof config!=='object') { this.$modal.msgError('草案中没有可展示的结构化配置'); return } this.analysisResult={ proposalId:data.proposal_id, proposalName:data.proposal_name, status:data.status, taskId:data.task_id, taskName:data.task_name, proposalConfig:config, isSavedProposal:true }; this.analysisConfig=config; this.analysisTab='objects'; this.analysisOpen=true; this.loadProposalVersions(data.task_id) }).catch(() => {}) },
    loadProposalVersions(taskId) { if (!taskId) { this.proposalVersions=[]; return } listResource('proposals',{ pageNum:1, pageSize:100, taskId }).then(result => { this.proposalVersions=(result.rows || []).sort((a,b) => Number(b.proposal_id)-Number(a.proposal_id)) }).catch(() => { this.proposalVersions=[] }) },
