    reviewProposalRow(row, decision) { const title=decision==='APPROVED'?'审核通过':'驳回草案'; const message=decision==='APPROVED'?'确认审核通过这份配置草案？通过后才允许导入本体平台。':'请填写驳回原因'; const prompt=decision==='REJECTED' ? this.$prompt(message,title,{inputPlaceholder:'例如：对象字段映射需要补充',inputType:'textarea',inputValidator:value => !!String(value || '').trim() || '请填写驳回原因'}) : this.$modal.confirm(message).then(() => ({ value:'' })); prompt.then(({ value }) => reviewProposal(row.proposal_id,{ decision, comment:value || '' })).then(() => { this.$modal.msgSuccess('审核结果已保存'); this.load() }).catch(() => {}) },
    escape(value) { return String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;') },
    countOf(value) { return Array.isArray(value) ? value.length : 0 },
    relationSourceLabel(value) { return ({ businessRule:'业务规则文档',foreignKey:'数据库外键',m2mReification:'关联表外键',columnNameInference:'表和字段命名推断',joinTableInference:'关联表结构推断',primaryKey:'数据库主键',document:'Wiki 文档',queryPattern:'SQL 样例',schema:'数据库结构',rdb:'数据库表结构',explicitColumnFormula:'字段公式',LLM_WIKI:'LLM Wiki 资料' })[value] || value || '未知' },
    objectLabel(row) { const description=String(row && row.description || '').trim(); return row && description && description.length<=80 ? (row.name || row.table || row.technicalName || '未命名对象') : (row && (row.table || row.technicalName || row.name) || '未命名对象') },
    propertyLabel(row) { const description=String(row && row.description || '').trim(); return row && description && description.length<=120 ? (row.name || row.column || row.technicalName || '未命名字段') : (row && (row.column || row.technicalName || row.name) || '未命名字段') },
    objectName(id) { const row=(this.analysisConfig.objects || []).find(item => String(item.id)===String(id)); return row ? (row.table || row.technicalName || this.objectLabel(row)) : String(id || '').replace(/^object_/,'') || '未关联对象' },
    propertyName(id) { const row=(this.analysisConfig.properties || []).find(item => String(item.id)===String(id)); return row ? (row.column || row.technicalName || this.propertyLabel(row)) : String(id || '').replace(/^property_/,'') || '未关联字段' },
    candidateReferenceName(value) { const id=String(value || ''); if (!id) return '未关联'; const object=(this.analysisConfig.objects || []).find(item => String(item.id)===id); if (object) return this.objectName(object.id); const property=(this.analysisConfig.properties || []).find(item => String(item.id)===id); if (property) return this.propertyName(property.id); const action=(this.analysisConfig.actions || []).find(item => String(item.id)===id); if (action) return this.actionLabel(action); const relation=(this.analysisConfig.relations || []).find(item => String(item.id)===id); if (relation) return this.relationLabel(relation); const logic=(this.analysisConfig.logics || []).find(item => String(item.id)===id); if (logic) return logic.name || '业务逻辑'; const flow=(this.analysisConfig.serviceFlows || []).find(item => String(item.id)===id); if (flow) return this.flowName(flow); const permission=(this.analysisConfig.permissionCandidates || []).find(item => String(item.id)===id); if (permission) return this.operationText(permission.operation) + ' ' + this.objectName(permission.resourceId); if (id==='schema') return '数据库结构'; if (id==='taxonomy') return '业务分类'; if (id==='llmWiki') return 'LLM Wiki'; let readable=id; while (/^(object|property|action|relation|flow|permission)_/.test(readable)) readable=readable.replace(/^(object|property|action|relation|flow|permission)_/,''); const operation=readable.match(/\.(READ|INSERT|UPDATE|DELETE)$/); return operation ? readable.replace(/\.(READ|INSERT|UPDATE|DELETE)$/,' · ' + this.operationText(operation[1])) : readable },
    relationLabel(row) { return row && row.sourceObjectId && row.targetObjectId ? this.objectName(row.sourceObjectId) + ' 关联 ' + this.objectName(row.targetObjectId) : this.candidateReferenceName(row && row.name) },
    actionLabel(row) { const name=String(row && row.name || ''); const match=name.match(/^(READ|INSERT|UPDATE|DELETE)\b/i); const operation=(row && row.operation) || (match && match[1]); return operation && row && row.objectId && match ? this.operationText(operation) + ' ' + this.objectName(row.objectId) : (name || (operation ? this.operationText(operation) : '未命名动作')) },
    flowStepsText(steps) { return (Array.isArray(steps) ? steps : []).map(id => { const action=(this.analysisConfig.actions || []).find(item => String(item.id)===String(id)); return action ? this.actionLabel(action) : this.candidateReferenceName(id) }).join(' → ') || '未配置步骤' },
    flowName(row) { return row && Array.isArray(row.steps) && row.steps.length ? this.flowStepsText(row.steps) : this.candidateReferenceName(row && row.name) },
    candidateStatusText(value) { return ({NEEDS_REVIEW:'待审核',DRAFT:'待审核',REVIEWED:'待审核',APPROVED:'已通过',REJECTED:'已驳回',IMPORTED:'已导入',ACTIVE:'已启用',DISABLED:'已停用'})[String(value || '').toUpperCase()] || value || '未设置' },
    riskText(value) { return ({LOW:'低',MEDIUM:'中',HIGH:'高',CRITICAL:'严重'})[String(value || '').toUpperCase()] || value || '未评估' },
    operationText(value) { return ({READ:'查询',SELECT:'查询',INSERT:'新增',UPDATE:'更新',DELETE:'删除'})[String(value || '').toUpperCase()] || value || '未指定' },
    triggerText(value) { return ({MCP_REQUEST:'工具 / API 请求',MANUAL:'人工触发',SCHEDULE:'定时触发',EVENT:'事件触发',WEBHOOK:'Webhook 回调'})[String(value || '').toUpperCase()] || value || '未指定' },
    subjectTypeText(value) { return ({ROLE:'角色',USER:'用户',GROUP:'用户组',SERVICE:'服务账号'})[String(value || '').toUpperCase()] || value || '未指定' },
    subjectsText(values) { const labels={ontology_reader:'只读角色',ontology_operator:'业务操作角色'}; return (Array.isArray(values) ? values : []).map(value => labels[value] || value).join('、') || '未指定' },
    booleanText(value) { if (value===true || String(value).toLowerCase()==='true') return '是'; if (value===false || String(value).toLowerCase()==='false') return '否'; return '未设置' },
    warningCodeText(value) { return ({LOW_QUALITY_TABLE:'表结构证据不足',NO_PROCESSABLE_TABLE:'没有可分析的数据表',TAXONOMY_CYCLE:'层级关系形成循环',NO_BUSINESS_DOCUMENT:'缺少业务文档',AMBIGUOUS_RELATION_INFERENCE:'关系推断存在歧义',INFERRED_RELATION_REVIEW:'推断关系待审核',DUPLICATE_OBJECT:'对象重复',BROKEN_RELATION:'关系引用缺失',UNMAPPED_QUERY_PATTERN:'SQL 样例未匹配数据表',LLM_SUGGESTIONS_UNPARSED:'模型建议未解析'})[value] || '待检查项' },
    diffCategoryText(value) { return ({objects:'对象',properties:'属性',identitySpecs:'主键定义',dataProfiles:'数据画像',relations:'关系',mappings:'字段映射',derivedProperties:'计算属性',validationRules:'校验规则',axioms:'本体公理',logics:'业务逻辑',actions:'业务动作',serviceFlows:'服务流',permissionCandidates:'权限候选',queryPatterns:'SQL 样例',terms:'业务术语',semanticMappings:'语义映射',governanceRules:'治理规则',warnings:'告警',evidence:'证据','taxonomy.nodes':'分类节点','taxonomy.edges':'层级关系'})[value] || '其他' },
    diffChangeText(value) { return ({ADDED:'新增',MODIFIED:'修改',REMOVED:'移除',新增:'新增',修改:'修改',移除:'移除'})[value] || '未分类' },
    formatConfidence(value) { const score=Number(value); return Number.isFinite(score) ? Math.round(score*100) + '%' : '—' },
    openAnswerChat() { if (!this.analysisResult.taskId) { this.$modal.msgWarning('当前草案没有关联分析任务，无法进入分析问答') ; return } this.analysisOpen=false; this.$router.push({ path:'/ontology/chat', query:{ scopeType:'ANALYSIS', scopeId:String(this.analysisResult.taskId), proposalId:this.analysisResult.proposalId ? String(this.analysisResult.proposalId) : undefined, returnTo:'/ontology/proposal' } }) },
    downloadCurrentProposal(format) { const row={ proposal_id:this.analysisResult.proposalId, proposal_name:this.analysisResult.proposalName || '本体配置草案' }; this.downloadProposal(row,format) },
    connectionHtml(data) {
      const product = this.escape(data && data.databaseProduct || '数据库')
      const version = this.escape(data && data.databaseVersion || '已连接')
      const connection = this.escape(data && data.connection || '连接已建立')
      return `<div style="padding:4px 2px 2px;color:#24324b"><div style="display:flex;align-items:center;margin-bottom:18px"><span style="display:inline-flex;align-items:center;justify-content:center;width:34px;height:34px;border-radius:50%;background:#e9f8ef;color:#20a464;font-size:22px;margin-right:12px">✓</span><div><div style="font-size:16px;font-weight:600;line-height:24px">数据库连接成功</div><div style="font-size:12px;color:#8a96a8;line-height:20px">已完成连接握手，可继续扫描数据源</div></div></div><div style="border:1px solid #e8edf4;border-radius:8px;background:#f8fafc;padding:2px 14px"><div style="display:flex;justify-content:space-between;gap:20px;padding:11px 0;border-bottom:1px solid #edf1f5"><span style="color:#8a96a8">数据库</span><strong style="font-weight:500">${product}</strong></div><div style="display:flex;justify-content:space-between;gap:20px;padding:11px 0;border-bottom:1px solid #edf1f5"><span style="color:#8a96a8">版本</span><span style="text-align:right">${version}</span></div><div style="padding:11px 0"><div style="color:#8a96a8;margin-bottom:5px">连接地址</div><div style="font-size:12px;line-height:18px;word-break:break-all;color:#526174">${connection}</div></div></div></div>`
    }
  }
}
</script>
